/* Bearer auth gate. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* Record a heartbeat (e.g. backup task) into the heartbeats table. */
const body = ($('Webhook Heartbeat').first().json.body) || {};
const job = String(body.job || 'unknown').slice(0, 40);
const ok = body.ok === true || body.ok === 1 || body.ok === 'true' ? 1 : 0;
const detail = String(body.detail || '').slice(0, 500);
const api = (method, path, qs, payload) => this.helpers.httpRequest({ method, url: 'http://localhost:5678/api/v1' + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body: payload });
const tables = (await api('GET', '/data-tables', { limit: 100 })).data || [];
const id = (tables.find((t) => t.name === 'heartbeats') || {}).id;
if (!id) return [{ json: { ok: false, error: 'heartbeats table missing (run deploy.mjs)' } }];
await api('POST', '/data-tables/' + id + '/rows', null, { data: [{ job, ok, detail }] });
return [{ json: { ok: true, job, ok_flag: ok, at: new Date().toISOString() } }];
